"use client";

import { useEffect, useMemo, useState } from "react";
import { AdminApiError, adminApi, type DashboardOverview, type HealthState } from "../lib/api";
import { adminSecurityNotes } from "../lib/security";

const numberFormatter = new Intl.NumberFormat("tr-TR");
const dateFormatter = new Intl.DateTimeFormat("tr-TR", {
  day: "2-digit",
  month: "long",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit"
});

const navItems: ReadonlyArray<{ label: string; icon: string; active?: boolean; count?: "users" | "reports" | "content" | "mesh" }> = [
  { label: "Genel bakış", icon: "grid", active: true },
  { label: "Kullanıcılar", icon: "users", count: "users" },
  { label: "Şikâyetler", icon: "flag", count: "reports" },
  { label: "İçerik kuyruğu", icon: "layers", count: "content" },
  { label: "Mesh sağlığı", icon: "pulse", count: "mesh" }
];

const emptyOverview: DashboardOverview = {
  generatedAt: "",
  users: { total: 0, active24h: 0, pendingVerification: 0, newThisWeek: 0 },
  reports: { open: 0, urgent: 0, resolvedToday: 0, medianResponseMinutes: 0 },
  content: { pendingReview: 0, removedToday: 0, flaggedMedia: 0, appeals: 0 },
  mesh: { state: "offline", healthyNodes: 0, totalNodes: 0, averageLatencyMs: 0, lastSyncAt: "" },
  activity: []
};

function formatNumber(value: number): string {
  return numberFormatter.format(value);
}

function formatTime(value: string): string {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : dateFormatter.format(date);
}

function relativeTime(value: string): string {
  if (!value) return "—";
  const elapsedMinutes = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 60000));
  if (elapsedMinutes < 1) return "az önce";
  if (elapsedMinutes < 60) return `${elapsedMinutes} dk önce`;
  const elapsedHours = Math.round(elapsedMinutes / 60);
  return elapsedHours < 24 ? `${elapsedHours} sa önce` : `${Math.round(elapsedHours / 24)} gün önce`;
}

function Icon({ name }: { name: string }) {
  const common = { width: 20, height: 20, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  if (name === "grid") return <svg {...common}><rect x="3" y="3" width="7" height="7" rx="1" /><rect x="14" y="3" width="7" height="7" rx="1" /><rect x="3" y="14" width="7" height="7" rx="1" /><rect x="14" y="14" width="7" height="7" rx="1" /></svg>;
  if (name === "users") return <svg {...common}><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" /></svg>;
  if (name === "flag") return <svg {...common}><path d="M5 21V4" /><path d="M5 4c5-3 9 3 14 0v10c-5 3-9-3-14 0" /></svg>;
  if (name === "layers") return <svg {...common}><path d="m12 2 9 5-9 5-9-5 9-5Z" /><path d="m3 12 9 5 9-5" /><path d="m3 17 9 5 9-5" /></svg>;
  if (name === "pulse") return <svg {...common}><path d="M3 12h4l3-8 4 16 3-8h4" /></svg>;
  if (name === "settings") return <svg {...common}><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.4 1.4-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-2v-.5a1.7 1.7 0 0 0-1.03-1.56 1.7 1.7 0 0 0-1.88.34l-.06.06-1.4-1.4.06-.06A1.7 1.7 0 0 0 9.4 15a1.7 1.7 0 0 0-1.56-1.03H7v-2h.5A1.7 1.7 0 0 0 9.06 11a1.7 1.7 0 0 0-.34-1.88l-.06-.06 1.4-1.4.06.06A1.7 1.7 0 0 0 12 8.06 1.7 1.7 0 0 0 13.03 6.5V6h2v.5A1.7 1.7 0 0 0 16.06 8a1.7 1.7 0 0 0 1.88-.34L18 7.6l1.4 1.4-.06.06A1.7 1.7 0 0 0 19.4 11c.17.62.75 1.03 1.39 1.03H21v2h-.21c-.64 0-1.22.4-1.39.97Z" /></svg>;
  if (name === "search") return <svg {...common}><circle cx="11" cy="11" r="7" /><path d="m20 20-4-4" /></svg>;
  if (name === "shield") return <svg {...common}><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" /><path d="m9 12 2 2 4-4" /></svg>;
  return <svg {...common}><circle cx="12" cy="12" r="9" /></svg>;
}

function healthLabel(state: HealthState): string {
  return state === "healthy" ? "Sağlıklı" : state === "degraded" ? "Kısmi sorun" : "Çevrimdışı";
}

function HealthPill({ state }: { state: HealthState }) {
  return <span className={`health-pill ${state}`}><span className="health-dot" />{healthLabel(state)}</span>;
}

function MetricCard({ title, value, caption, icon, tone, footer }: { title: string; value: string; caption: string; icon: string; tone: string; footer?: string }) {
  return (
    <article className="metric-card">
      <div className={`metric-icon ${tone}`}><Icon name={icon} /></div>
      <div className="metric-heading"><span>{title}</span><span className="metric-menu">•••</span></div>
      <strong className="metric-value">{value}</strong>
      <div className="metric-caption">{caption}</div>
      {footer && <div className="metric-footer">{footer}</div>}
    </article>
  );
}

export default function AdminDashboard() {
  const [overview, setOverview] = useState<DashboardOverview>(emptyOverview);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);

  useEffect(() => {
    let mounted = true;
    adminApi.getOverview()
      .then((data) => {
        if (!mounted) return;
        setOverview(data);
        setLastRefresh(new Date());
      })
      .catch((reason: unknown) => {
        if (!mounted) return;
        const message = reason instanceof AdminApiError && reason.status === 401
          ? "Yönetici oturumu bulunamadı. MFA ile tekrar giriş yapın."
          : "API'ye ulaşılamadı. Operasyon verileri canlı bağlantı kurulunca görünecek.";
        setError(message);
      })
      .finally(() => mounted && setLoading(false));
    return () => { mounted = false; };
  }, []);

  const meshSummary = useMemo(() => `${overview.mesh.healthyNodes}/${overview.mesh.totalNodes}`, [overview.mesh]);
  const updatedLabel = lastRefresh ? formatTime(lastRefresh.toISOString()) : "Bağlantı bekleniyor";

  return (
    <div className="admin-shell">
      <aside className="sidebar">
        <div className="brand"><span className="brand-mark">a</span><div><strong>alevi</strong><span>operasyon merkezi</span></div></div>
        <div className="workspace-label">YÖNETİM</div>
        <nav aria-label="Yönetim bölümleri">
          {navItems.map((item) => {
            const count = item.count === "users" ? overview.users.pendingVerification : item.count === "reports" ? overview.reports.open : item.count === "content" ? overview.content.pendingReview : item.count === "mesh" ? overview.mesh.totalNodes - overview.mesh.healthyNodes : 0;
            return <a className={`nav-item ${item.active ? "active" : ""}`} href={`#${item.label.toLocaleLowerCase("tr-TR").replace(/\s+/g, "-")}`} key={item.label}><Icon name={item.icon} /><span>{item.label}</span>{item.count && count > 0 ? <b>{formatNumber(count)}</b> : null}</a>;
          })}
        </nav>
        <div className="sidebar-bottom"><a className="nav-item" href="#ayarlar"><Icon name="settings" /><span>Ayarlar</span></a><div className="admin-identity"><span className="avatar">AY</span><div><strong>Ayşe Y.</strong><small>Baş yönetici</small></div><span className="identity-dots">•••</span></div></div>
      </aside>

      <main className="main-content">
        <header className="topbar"><div className="breadcrumbs"><span>Yönetim</span><i>/</i><strong>Genel bakış</strong></div><div className="topbar-actions"><span className="secure-label"><Icon name="shield" /> Güvenli oturum</span><button className="icon-button" aria-label="Arama"><Icon name="search" /></button><button className="notification-button" aria-label="Bildirimler"><span>3</span>●</button><span className="top-avatar">AY</span></div></header>
        <div className="content-wrap">
          <section className="page-intro"><div><p className="eyebrow">21 EYLÜL 2026 · PAZARTESİ</p><h1>Günaydın, Ayşe</h1><p className="intro-copy">Topluluğunuzun bugünkü operasyon görünümü.</p></div><div className="intro-status"><span className="live-dot" /> Canlı izleme açık<span className="intro-divider" /> {updatedLabel}</div></section>
          {error && <div className="api-alert" role="status"><strong>Canlı veri bekleniyor</strong><span>{error}</span><button onClick={() => window.location.reload()}>Yenile</button></div>}

          <section className="metric-grid" aria-label="Özet metrikler">
            <MetricCard title="Toplam kullanıcı" value={loading ? "—" : formatNumber(overview.users.total)} caption="kayıtlı topluluk üyesi" icon="users" tone="wine" footer={`+${formatNumber(overview.users.newThisWeek)} bu hafta`} />
            <MetricCard title="Açık şikâyetler" value={loading ? "—" : formatNumber(overview.reports.open)} caption={`${formatNumber(overview.reports.urgent)} yüksek öncelikli`} icon="flag" tone="amber" footer={`${formatNumber(overview.reports.resolvedToday)} bugün çözüldü`} />
            <MetricCard title="İçerik inceleme" value={loading ? "—" : formatNumber(overview.content.pendingReview)} caption="işlem bekleyen içerik" icon="layers" tone="blue" footer={`${formatNumber(overview.content.appeals)} itiraz bekliyor`} />
            <MetricCard title="Mesh sağlığı" value={loading ? "—" : meshSummary} caption="node erişilebilir" icon="pulse" tone="green" footer={`${formatNumber(overview.mesh.averageLatencyMs)} ms ort. gecikme`} />
          </section>

          <section className="main-grid">
            <article className="panel activity-panel"><div className="panel-heading"><div><p className="eyebrow">OPERASYON AKIŞI</p><h2>Son aktiviteler</h2></div><button className="text-button">Tümünü gör <span>→</span></button></div><div className="activity-list">{overview.activity.length === 0 ? <div className="empty-state"><span className="empty-symbol">◌</span><strong>{loading ? "Aktiviteler yükleniyor" : "Görüntülenecek yeni aktivite yok"}</strong><span>Canlı API bağlantısı kurulduğunda olaylar burada listelenir.</span></div> : overview.activity.map((event) => <div className="activity-row" key={event.id}><span className={`activity-icon ${event.kind}`}><Icon name={event.kind === "report" ? "flag" : event.kind === "mesh" ? "pulse" : event.kind === "user" ? "users" : "layers"} /></span><div><strong>{event.title}</strong><p>{event.detail}</p></div><time>{relativeTime(event.occurredAt)}</time></div>)}</div></article>
            <article className="panel health-panel"><div className="panel-heading"><div><p className="eyebrow">ALTYAPI</p><h2>Mesh sağlığı</h2></div><HealthPill state={overview.mesh.state} /></div><div className="health-visual"><div className={`health-ring ${overview.mesh.state}`}><strong>{overview.mesh.totalNodes ? Math.round((overview.mesh.healthyNodes / overview.mesh.totalNodes) * 100) : 0}%</strong><span>erişilebilir</span></div><div className="health-details"><div><span>Aktif node</span><strong>{meshSummary}</strong></div><div><span>Son senkronizasyon</span><strong>{formatTime(overview.mesh.lastSyncAt)}</strong></div><div><span>Ortalama gecikme</span><strong>{formatNumber(overview.mesh.averageLatencyMs)} ms</strong></div></div></div><div className="node-bars"><div className="node-bar-label"><span>Node kullanılabilirliği</span><strong>{overview.mesh.healthyNodes} / {overview.mesh.totalNodes}</strong></div><div className="progress-track"><span style={{ width: `${overview.mesh.totalNodes ? (overview.mesh.healthyNodes / overview.mesh.totalNodes) * 100 : 0}%` }} /></div></div><button className="outline-button">Mesh ayrıntılarını aç <span>→</span></button></article>
          </section>

          <section className="bottom-grid"><article className="panel quick-panel"><div className="panel-heading"><div><p className="eyebrow">HIZLI GÖRÜNÜM</p><h2>Bugünün özeti</h2></div><span className="date-badge">21 Eyl</span></div><div className="quick-list"><div><span className="quick-icon green">✓</span><span>Çözülen şikâyetler</span><strong>{formatNumber(overview.reports.resolvedToday)}</strong></div><div><span className="quick-icon blue">↗</span><span>Aktif kullanıcı (24 sa)</span><strong>{formatNumber(overview.users.active24h)}</strong></div><div><span className="quick-icon amber">!</span><span>Kaldırılan içerik</span><strong>{formatNumber(overview.content.removedToday)}</strong></div><div><span className="quick-icon wine">◷</span><span>Ort. yanıt süresi</span><strong>{formatNumber(overview.reports.medianResponseMinutes)} dk</strong></div></div></article><article className="panel security-panel"><div className="panel-heading"><div><p className="eyebrow">GÜVENLİK MERKEZİ</p><h2>Kontrol noktaları</h2></div><span className="security-score">4/5</span></div><div className="security-list">{adminSecurityNotes.slice(0, 4).map((note) => <div className="security-row" key={note.title}><span className={`security-status ${note.tone}`} /> <span>{note.title}</span><small>{note.tone === "good" ? "Etkin" : "İncele"}</small></div>)}</div><a className="security-link" href="#security">Güvenlik kontrollerini görüntüle <span>→</span></a></article></section>
          <footer className="page-footer"><span>Alevi Operasyon Merkezi · v0.1 iskelet</span><span>Veriler amaç sınırlı ve maskeli gösterilir · KVKK</span></footer>
        </div>
      </main>
    </div>
  );
}
